<?php
$notification_count = isset($notification_count) ? max(0, (int) $notification_count) : 0;
$notification_relative_time = function ($value) use ($labels) {
    $timestamp = strtotime((string) $value);
    if ($timestamp === FALSE) {
        return '';
    }
    $seconds = max(0, time() - $timestamp);
    if ($seconds < 60) {
        return $labels['notifications_time_just_now'];
    }
    foreach (array(31536000 => 'year', 2592000 => 'month', 604800 => 'week', 86400 => 'day', 3600 => 'hour', 60 => 'minute') as $size => $unit) {
        if ($seconds >= $size) {
            return (int) floor($seconds / $size) . ' ' . $labels['notifications_time_' . $unit] . ' ' . $labels['notifications_time_ago'];
        }
    }
    return $labels['notifications_time_just_now'];
};
